 p=Path('/workspace/scratch/8d52181bc639/research_reading')/('cycle3' if rid=='R01525' else 'queue')/(rid+'.pdf')
 sha=hashlib.sha256(p.read_bytes()).hexdigest()
 rows.append(dict(record_id=rid,title=title,doi=doi,decision=decision,primary_EC=ec,source_url=url,source_sha256=sha,pdf_pages=len(fitz.open(p)),publication_identity_url=pub,source_version=ver,evidence_anchor=anchor,scope_rationale=scope,limitation_or_remaining_gap=gap,review_method='Single source-based adjudication under logged amendment; no human independent vote asserted'))
 reasons={1:('Met for publication identity' if decision=='Exclude' else 'Pending',ver),2:('Not met' if rid in ['R01525','R02392'] else ('Met' if rid=='R01837' else 'Pending'),scope),3:('Not met' if rid=='R01837' else 'Met',scope),4:('Not met in required scope' if rid in ['R01525','R01837','R02392'] else 'Met locally',scope),5:('Met for source availability/local observations; does not cureIC2/3 failure', 'Local results inspectable; scope failure is absence of required independent inference tenant setting, not missingfulltext.'),6:('Met','Published2024(R01525),2022(R01837),2025(R02392); within protocol window.')}
